"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View12 from "./components/feature-sections/variants/13-stage-tabs";
const variants = {"stage-tabs":View12};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "stage-tabs"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "stage-tabs", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, type Transition, useInView, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";
import { ARTEMIS_EASE_IN_OUT, ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { AutomationStage, InsightsStage, LearningStage, WorkspaceStage } from "./13-stage-tabs/stages";
import type { ArtemisFeatureContent, ArtemisFeatureItem } from "../content";
const DEFAULT = {
    items: [
        {
            label: "Unified workspace",
            title: "Every conversation stays in context",
            description: "Bring requests, customer history, and team decisions into one calm workspace.",
        },
        {
            label: "Automated handoffs",
            title: "Routine work moves without chasing",
            description: "Route requests, assign owners, and prepare the next step while your team stays focused.",
        },
        {
            label: "Live insights",
            title: "See what needs attention now",
            description: "Turn every interaction into a clear view of workload, quality, and emerging patterns.",
        },
        {
            label: "Always improving",
            title: "The system learns from resolved work",
            description: "Capture feedback and approved answers so the next response starts from better context.",
        },
    ],
} satisfies ArtemisFeatureContent;
/** Each slot's stage art, and the slug its tab and panel ids use. */
const STAGE_ART = [WorkspaceStage, AutomationStage, InsightsStage, LearningStage];
const STAGE_KEYS = ["workspace", "automation", "insights", "learning"];
const stageKey = (i: number) => (i < STAGE_KEYS.length ? STAGE_KEYS[i] : `stage-${i + 1}`);
const TAB_BASE = "art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:p-0 art:font-normal";
const TAB_TAIL = "art:relative art:min-h-12 art:min-w-[16.5rem] art:flex-1 art:snap-center art:border-border art:border-r art:px-6 art:py-5 art:text-left art:outline-none art:transition-colors art:last:border-r-0 art:focus-visible:bg-muted/60 art:@min-[640px]/artemis:min-w-[20rem] art:@min-[1024px]/artemis:min-w-0";
const TAB_ACTIVE = `${TAB_BASE} art:hover:bg-transparent art:hover:text-inherit ${TAB_TAIL} art:text-foreground art:rounded-full`;
const TAB_IDLE = `${TAB_BASE} ${TAB_TAIL} art:text-muted-foreground art:hover:bg-muted/35 art:hover:text-foreground art:rounded-full`;
const ADVANCE_MS = 6500;
const PANEL_SWAP: Transition = { duration: 0.46, ease: ARTEMIS_EASE_IN_OUT };
const COPY_ENTER: Transition = { duration: 0.42, ease: ARTEMIS_EASE_OUT, delay: 0.08 };
const WINDOW_ENTER: Transition = { duration: 0.58, ease: ARTEMIS_EASE_OUT, delay: 0.12 };
const INSTANT: Transition = { duration: 0 };
const PANEL_HIDDEN = { opacity: 0, filter: "blur(8px)", scale: 1.012 };
const PANEL_SHOWN = { opacity: 1, filter: "blur(0px)", scale: 1 };
const PANEL_GONE = { opacity: 0, filter: "blur(6px)", scale: 0.992 };
function useReducedAfterMount(): boolean {
    const prefers = useReducedMotion() ?? false;
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    return mounted && prefers;
}
export default function FeatureSectionsStageTabs({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const items: ArtemisFeatureItem[] = copy.items;
    const count = items.length;
    const reduce = useReducedAfterMount();
    const baseId = useId();
    const sectionRef = useRef<HTMLElement>(null);
    const listRef = useRef<HTMLDivElement>(null);
    const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);
    const inView = useInView(sectionRef);
    const [active, setActive] = useState(0);
    const first = useRef(true);
    const remaining = useRef(ADVANCE_MS);
    useEffect(() => {
        remaining.current = ADVANCE_MS;
    }, [active]);
    useEffect(() => {
        if (!inView || reduce || count < 2)
            return;
        const started = performance.now();
        const id = setTimeout(() => setActive((a) => (a + 1) % count), remaining.current);
        return () => {
            clearTimeout(id);
            remaining.current = Math.max(0, remaining.current - (performance.now() - started));
        };
    }, [active, inView, reduce, count]);
    useEffect(() => {
        if (first.current) {
            first.current = false;
            return;
        }
        const list = listRef.current;
        const tab = tabRefs.current[active];
        if (!list || !tab)
            return;
        const listBox = list.getBoundingClientRect();
        const tabBox = tab.getBoundingClientRect();
        const left = list.scrollLeft + tabBox.left - listBox.left + tabBox.width / 2 - list.clientWidth / 2;
        list.scrollTo({ left, behavior: "smooth" });
    }, [active]);
    const select = (index: number, focus: boolean) => {
        setActive(index);
        if (focus)
            tabRefs.current[index]?.focus();
    };
    const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        if (count === 0)
            return;
        let next: number | null = null;
        if (event.key === "ArrowRight")
            next = (active + 1) % count;
        else if (event.key === "ArrowLeft")
            next = (active - 1 + count) % count;
        else if (event.key === "Home")
            next = 0;
        else if (event.key === "End")
            next = count - 1;
        if (next === null)
            return;
        event.preventDefault();
        select(next, true);
    };
    const shown = active < count ? active : 0;
    const stage = items[shown];
    const shownKey = stageKey(shown);
    const StageArt = STAGE_ART[shown % STAGE_ART.length];
    const panelTransition = reduce ? INSTANT : PANEL_SWAP;
    return (<>
      <section ref={sectionRef} className="art:w-full art:px-3 art:py-20 art:@min-[640px]/artemis:px-6">
        <style>
          {"\n        @keyframes artemis-68c9a58-artemis-feature-stage-progress {\n          from { transform: scaleX(0); }\n          to { transform: scaleX(1); }\n        }\n      "}
        </style>
        <div className="art:mx-auto art:w-full art:max-w-[88rem] art:overflow-hidden art:rounded-xl art:border art:border-border art:bg-background">
          <div ref={listRef} role="tablist" aria-label="Product capabilities" className="art:scrollbar-hide art:flex art:snap-x art:snap-mandatory art:overflow-x-auto art:border-border art:border-b" onKeyDown={onKeyDown}>
            {items.map((s, i) => {
            const on = i === active;
            const key = stageKey(i);
            return (<motion.button key={key} ref={(el) => {
                    tabRefs.current[i] = el;
                }} type="button" className={on ? TAB_ACTIVE : TAB_IDLE} id={`${baseId}-tab-${key}`} role="tab" aria-controls={`${baseId}-panel-${key}`} aria-selected={on} tabIndex={on ? 0 : -1} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => select(i, false)}>
                  {on ? (<span className="art:absolute art:inset-x-0 art:top-0 art:h-0.5 art:overflow-hidden art:bg-border">
                      <span key={active} className="art:absolute art:inset-0 art:origin-left art:bg-foreground" style={{
                        animationName: "artemis-68c9a58-artemis-feature-stage-progress",
                        animationDuration: "6500ms",
                        animationTimingFunction: "linear",
                        animationFillMode: "forwards",
                        animationPlayState: inView && !reduce ? "running" : "paused",
                    }}/>
                    </span>) : null}
                  <span className="art:block art:whitespace-nowrap art:font-medium art:text-base art:leading-none art:@min-[640px]/artemis:text-lg">
                    {s.label ?? s.title}
                  </span>
                </motion.button>);
        })}
          </div>
          <div className="art:relative art:min-h-[36rem] art:overflow-hidden art:@min-[640px]/artemis:min-h-[42rem]">
            <AnimatePresence mode="wait" initial={false}>
              {stage ? (<motion.div key={shownKey} id={`${baseId}-panel-${shownKey}`} role="tabpanel" aria-labelledby={`${baseId}-tab-${shownKey}`} className="art:absolute art:inset-0" initial={PANEL_HIDDEN} animate={PANEL_SHOWN} exit={PANEL_GONE} transition={panelTransition}>
                <div className="art:absolute art:inset-0">
                  <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:overflow-hidden">
                    <img src="/assets/artemis/673224b3283d82b96134.webp" alt="" width="768" height="768" loading="lazy" decoding="async" className="art:size-full art:object-cover" style={{ objectPosition: "center" }}/>
                    <div className="art:absolute art:inset-0 art:bg-background/10 art:dark:bg-background/65"/>
                  </div>
                  <div className="art:absolute art:inset-0 art:bg-background/10 art:dark:bg-background/70"/>
                  <motion.div className="art:relative art:z-10 art:mx-auto art:max-w-2xl art:px-6 art:pt-10 art:text-center art:@min-[640px]/artemis:pt-12" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={reduce ? INSTANT : COPY_ENTER}>
                    <h3 className="art:text-balance art:font-medium art:text-xl art:text-foreground art:tracking-tight">
                      {stage.title}
                    </h3>
                    <p className="art:mx-auto art:mt-3 art:max-w-xl art:text-pretty art:text-foreground/65 art:text-sm art:leading-6 art:dark:text-foreground/78 art:@min-[640px]/artemis:text-base">
                      {stage.description}
                    </p>
                  </motion.div>
                  <motion.div className="art:absolute art:inset-x-3 art:top-[11.25rem] art:bottom-[-3rem] art:@min-[640px]/artemis:inset-x-[8%] art:@min-[640px]/artemis:top-[11.5rem] art:@min-[640px]/artemis:bottom-[-5rem]" initial={{ opacity: 0, y: 26, scale: 0.985 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={reduce ? INSTANT : WINDOW_ENTER}>
                    <div className="art:h-full art:overflow-hidden art:rounded-t-2xl art:border art:border-border art:bg-background/95 art:backdrop-blur-xl">
                      <div className="art:flex art:h-12 art:items-center art:justify-between art:border-border art:border-b art:px-3 art:@min-[640px]/artemis:h-14 art:@min-[640px]/artemis:px-5">
                        <div className="art:flex art:items-center art:gap-3">
                          <span className="art:grid art:size-8 art:place-items-center art:border art:border-border art:bg-muted art:text-foreground art:rounded-full">
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-layers art:size-4" aria-hidden="true">
                              <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
                              <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
                              <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
                            </svg>
                          </span>
                          <span className="art:font-medium art:text-foreground art:text-sm">
                            {"Group A workspace"}
                          </span>
                        </div>
                        <div className="art:hidden art:items-center art:gap-2 art:rounded-lg art:border art:border-border art:bg-muted/45 art:px-3 art:py-2 art:text-muted-foreground art:text-xs art:@min-[640px]/artemis:flex">
                          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-search art:size-3.5" aria-hidden="true">
                            <path d="m21 21-4.34-4.34"/>
                            <circle cx="11" cy="11" r="8"/>
                          </svg>
                          {"Search conversations"}
                        </div>
                      </div>
                      <div className="art:h-[calc(100%-3rem)] art:@min-[640px]/artemis:h-[calc(100%-3.5rem)]">
                        <StageArt />
                      </div>
                    </div>
                  </motion.div>
                </div>
              </motion.div>) : null}
            </AnimatePresence>
          </div>
        </div>
      </section>
    </>);
}
